interface.definition:
a!localVariables(


  {

    #"SYSTEM_SYSRULES_gridField_v5"(
      label: "Application Details",
      labelPosition: "ABOVE",
      data: #"SYSTEM_SYSRULES_recordData"(
        recordType: #"urn:appian:record-type:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7",
        filters: {
          #"SYSTEM_SYSRULES_queryFilter"(
            field: #"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/3e4edb1b-316e-460a-81f3-b7e7315ce7c2",
            operator: "in",
            value: ri!appid,
            applyWhen: a!isNotNullOrEmpty(ri!appid)
          )
        },
        fields: {}
      ),
      showRefreshButton: true,
      showSearchBox: true,
      columns: {
        /* Application Name + Ref ID merged — matches Teams pattern */
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Application Name",
          value: #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: fv!row[
                  #"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/934fe72d-d285-4f56-bb33-55edd415c5de"
                ],
                link: #"SYSTEM_SYSRULES_recordLink"(
                  recordType: #"urn:appian:record-type:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7",
                  identifier: fv!identifier
                ),
                style: "STRONG"
              ),
              char(10),
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: if(
                  fv!row[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/3e4edb1b-316e-460a-81f3-b7e7315ce7c2"] < 100000,
                  "APP-" & text(
                    fv!row[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/3e4edb1b-316e-460a-81f3-b7e7315ce7c2"],
                    "00000"
                  ),
                  "APP-" & fv!row[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/3e4edb1b-316e-460a-81f3-b7e7315ce7c2"]
                ),
                color: "SECONDARY",
                size: "SMALL"
              )
            }
          ),
          sortField: #"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/934fe72d-d285-4f56-bb33-55edd415c5de"
        ),
        /* Description */
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Description",
          value: a!defaultValue(
            fv!row[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/fe3c2d5d-d09f-48a6-9692-dd3ee4f80925"],
            "–"
          ),
          sortField: #"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/fe3c2d5d-d09f-48a6-9692-dd3ee4f80925"
        ),
        /* Created By — null-safe with UAM_setUserName */
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Created By",
          value: #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: if(
                a!isNullOrEmpty(
                  fv!row[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/b7f7118c-46d1-454a-b1e5-43d6c512d680"]
                ),
                "No User",
                #"_a-0000eef8-4604-8000-9e54-011c48011c48_1121809"(
                  fv!row[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/b7f7118c-46d1-454a-b1e5-43d6c512d680"]
                )
              ),
              color: if(
                a!isNullOrEmpty(
                  fv!row[#"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/b7f7118c-46d1-454a-b1e5-43d6c512d680"]
                ),
                "NEGATIVE",
                "STANDARD"
              )
            )
          ),
          sortField: #"urn:appian:record-field:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/b7f7118c-46d1-454a-b1e5-43d6c512d680"
        ),
        /* Actions — pencil icon linked to edit PM */
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Actions",
          value:#"SYSTEM_SYSRULES_recordActionField_v1"(
            actions: #"SYSTEM_SYSRULES_recordActionItem"(
              action: #"urn:appian:record-action:v1:d82b71ee-1dd1-46f0-ba3e-d6849d0512f7/7da09602-a57a-441d-b194-522ad5982daf",
              identifier: fv!identifier
            ),

          ),
          width: "AUTO"
        )
      },
      refreshAfter: "RECORD_ACTION",
      validations: {}
    )
  }
)
